package com.coraline.feast;

import java.nio.file.*;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.LevelResource;
import com.coraline.entity.CharacterEntity;

/** The canonical Cat is retained as a native original, not reconstructed from
 * a backup when the old procedural or story realm is retired. */
final class CompleteEndingCatArchive extends SavedData {
    private final UUID reset;private final CompoundTag raw;private String problem="";
    private CompleteEndingCatArchive(UUID reset){this.reset=reset;raw=new CompoundTag();raw.putInt("Version",1);raw.putUUID("Reset",reset);raw.put("Owners",new CompoundTag());}
    private static boolean location(CompoundTag n){if(!n.hasUUID("Entity")||!n.contains("Dimension",Tag.TAG_STRING)||net.minecraft.resources.ResourceLocation.tryParse(n.getString("Dimension"))==null||!n.contains("Position",Tag.TAG_LONG))return false;var at=BlockPos.of(n.getLong("Position"));return Math.abs((long)at.getX())<=29999920&&Math.abs((long)at.getZ())<=29999920&&at.getY()>=-2048&&at.getY()<=2047;}
    private CompleteEndingCatArchive(UUID reset,CompoundTag n){this.reset=reset;raw=n.copy();try{if(!n.contains("Version",Tag.TAG_INT)||n.getInt("Version")!=1||!n.hasUUID("Reset")||!reset.equals(n.getUUID("Reset"))||!n.contains("Owners",Tag.TAG_COMPOUND)||n.getCompound("Owners").size()>4096)throw new IllegalArgumentException("Invalid Cat archive");var actors=new HashSet<UUID>();for(String key:n.getCompound("Owners").getAllKeys()){if(!UUID.fromString(key).toString().equals(key)||!n.getCompound("Owners").contains(key,Tag.TAG_COMPOUND))throw new IllegalArgumentException("Invalid Cat owner");var row=n.getCompound("Owners").getCompound(key);if(!row.contains("Source",Tag.TAG_COMPOUND)||!location(row.getCompound("Source"))||!actors.add(row.getCompound("Source").getUUID("Entity"))||!row.contains("Destination",Tag.TAG_LONG))throw new IllegalArgumentException("Invalid Cat admission");var destination=BlockPos.of(row.getLong("Destination"));if(Math.abs((long)destination.getX())>29999920||Math.abs((long)destination.getZ())>29999920||destination.getY()< -64||destination.getY()>319)throw new IllegalArgumentException("Invalid Cat destination");if(row.contains("Archived")){var result=row.getCompound("Archived");if(!row.contains("Archived",Tag.TAG_COMPOUND)||!location(result)||!result.getUUID("Entity").equals(row.getCompound("Source").getUUID("Entity"))||!result.getString("Dimension").equals("minecraft:overworld")||result.getLong("Position")!=row.getLong("Destination"))throw new IllegalArgumentException("Invalid Cat handoff");}}}catch(IllegalArgumentException bad){problem=bad.getMessage();}}
    private static String name(UUID reset){return "coraline_ending_cat_"+reset;}
    private static CompleteEndingCatArchive get(MinecraftServer server,UUID reset){var file=server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(reset)+".dat");return server.overworld().getDataStorage().computeIfAbsent(n->new CompleteEndingCatArchive(reset,n),()->Files.notExists(file,LinkOption.NOFOLLOW_LINKS)?new CompleteEndingCatArchive(reset):new CompleteEndingCatArchive(reset,new CompoundTag()),name(reset));}
    private boolean commit(MinecraftServer server){if(!problem.isEmpty())return false;try{var file=server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(reset)+".dat");if(Files.isSymbolicLink(file)||Files.isSymbolicLink(file.getParent()))throw new java.io.IOException("Ambiguous Cat archive");setDirty();server.overworld().getDataStorage().save();if(!com.coraline.rebirth.StoryRunStore.read(file).getCompound("data").equals(raw))throw new java.io.IOException("Cat archive checkpoint mismatch");return true;}catch(java.io.IOException|RuntimeException failed){problem="Cat archive could not be confirmed";return false;}}
    @Override public CompoundTag save(CompoundTag n){return n.merge(raw.copy());}
    static Optional<CompoundTag> archive(MinecraftServer server,UUID owner,UUID reset){
        var book=get(server,reset);if(!book.problem.isEmpty())return Optional.empty();var all=book.raw.getCompound("Owners");var row=all.getCompound(owner.toString());var scene=VisitData.get(server).scenes.get(owner);var source=row.contains("Source",Tag.TAG_COMPOUND)?row.getCompound("Source").copy():scene==null?new CompoundTag():scene.loop.story.getCompound("CanonicalStoryCat").copy();
        if(source.isEmpty())try{source=com.coraline.rebirth.StoryRunStore.get(server,owner).save().getCompound("PreviousRitual").getCompound("Retained").getCompound("Cat").copy();}catch(java.io.IOException failed){return Optional.empty();}
        if(source.isEmpty())return Optional.of(new CompoundTag());if(!location(source))return Optional.empty();var from=com.coraline.parents.FamilyData.level(server,source.getString("Dimension"));if(from!=null)LoopProps.hold(from,BlockPos.of(source.getLong("Position")));if(row.contains("Destination",Tag.TAG_LONG))LoopProps.hold(server.overworld(),BlockPos.of(row.getLong("Destination")));
        CharacterEntity original=null;for(var level:server.getAllLevels())if(level.getEntity(source.getUUID("Entity")) instanceof CharacterEntity actor){if(original!=null)return Optional.empty();original=actor;}if(original==null||!original.characterId().equals("cat")||!original.getPersistentData().hasUUID("CanonicalStoryCatOwner")||!owner.equals(original.getPersistentData().getUUID("CanonicalStoryCatOwner")))return Optional.empty();
        var palace=com.coraline.palace.PalaceSiteData.get(server).position(com.coraline.palace.PalaceSitePlan.Kind.PALACE).orElse(null);if(palace==null)return Optional.empty();LoopProps.hold(server.overworld(),palace);var destination=row.contains("Destination",Tag.TAG_LONG)?BlockPos.of(row.getLong("Destination")):com.coraline.tycoon.TycoonWorld.landing(server.overworld(),palace.west(4));if(destination==null||!com.coraline.tycoon.TycoonWorld.safeFeet(server.overworld(),destination))return Optional.empty();
        if(row.contains("Archived",Tag.TAG_COMPOUND)&&original.level()==server.overworld()&&original.blockPosition().equals(destination)&&original.isNoAi()&&original.isInvisible()&&original.isNoGravity()&&original.noPhysics&&!original.getPersistentData().hasUUID("ShowActorOwner"))return Optional.of(row.getCompound("Archived").copy());
        if(!all.contains(owner.toString())){if(all.size()>=4096)return Optional.empty();for(String key:all.getAllKeys())if(all.getCompound(key).getCompound("Source").getUUID("Entity").equals(original.getUUID()))return Optional.empty();source.putString("Dimension",original.level().dimension().location().toString());source.putLong("Position",original.blockPosition().asLong());row=new CompoundTag();row.put("Source",source.copy());row.putLong("Destination",destination.asLong());all.put(owner.toString(),row);if(!book.commit(server))return Optional.empty();}
        original.getNavigation().stop();original.stopRiding();net.minecraft.world.entity.Entity moved=original;if(original.level()!=server.overworld())moved=original.changeDimension(server.overworld(),new net.minecraftforge.common.util.ITeleporter(){@Override public net.minecraft.world.entity.Entity placeEntity(net.minecraft.world.entity.Entity entity,net.minecraft.server.level.ServerLevel current,net.minecraft.server.level.ServerLevel target,float yaw,java.util.function.Function<Boolean,net.minecraft.world.entity.Entity> reposition){var result=reposition.apply(false);if(result!=null)result.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(destination));return result;}});
        if(!(moved instanceof CharacterEntity cat)||!source.getUUID("Entity").equals(cat.getUUID()))return Optional.empty();cat.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(destination));cat.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);cat.fallDistance=0;cat.setNoAi(true);cat.setNoGravity(true);cat.noPhysics=true;cat.setInvisible(true);cat.setSilent(true);cat.setInvulnerable(true);cat.gameGesture(0,0);cat.getPersistentData().putUUID("CanonicalStoryCatEndingArchive",reset);for(String key:new String[]{"ShowActorReturn","ShowTravelOwner","ShowActorOwner","ShowActorSerial"})cat.getPersistentData().remove(key);
        var result=source.copy();result.putString("Dimension","minecraft:overworld");result.putLong("Position",destination.asLong());result.remove("FarewellDeparted");if(scene!=null){var existing=scene.loop.story.getCompound("CanonicalStoryCat");if(existing.hasUUID("Entity")&&!existing.getUUID("Entity").equals(cat.getUUID()))return Optional.empty();scene.loop.story.put("CanonicalStoryCat",result.copy());VisitData.get(server).setDirty();}if(!server.saveEverything(true,true,true))return Optional.empty();row.put("Archived",result.copy());return book.commit(server)?Optional.of(result):Optional.empty();
    }
}
